codeExample:
// SCSS
$color: red;
.container { color: $color; }

// Sass
$color: red
.container
  color: $color

.nav {
  ul {
    margin: 0;
    li { 
      padding: 5px;
      &:hover { color: red; }
    }
  }
}

@mixin center-content {
  display: flex;
  justify-content: center;
  align-items: center;
}

.container {
  @include center-content;
}

@mixin size($width) {
  @if type-of($width) != number {
    @error 'Width must be a number';
  }
  width: $width;
}
